answer:
Преобразование объекта в строку JSON можно сделать с помощью метода `JSON.stringify()`. Этот метод принимает объект и преобразует его в строку JSON. В данном примере используется этот метод для преобразования строки JSON в объект JavaScript.

```js
request.open("GET", requestURL);
request.responseType = "text"; // now we're getting a string!
request.send();

request.onload = function () {
  var superHeroesText = request.response; // get the string from the response
  var superHeroes = JSON.parse(superHeroesText); // convert it to an object
  populateHeader(superHeroes);
  showHeroes(superHeroes);
};
```

